ALTER TABLE ${primehrSchema}.spms_rating_case DROP CONSTRAINT ck_spms_rating_case_status;
ALTER TABLE ${primehrSchema}.spms_rating_case ADD CONSTRAINT ck_spms_rating_case_status CHECK(status IN ('OPEN','SUPERVISOR_SUBMITTED','CALIBRATION_OPEN','READY_FOR_FINALIZATION','FINALIZED','VOIDED'));
ALTER TABLE ${primehrSchema}.spms_rating_assessment DROP CONSTRAINT ck_spms_rating_assessment_type;
ALTER TABLE ${primehrSchema}.spms_rating_assessment ADD CONSTRAINT ck_spms_rating_assessment_type CHECK(assessment_type IN ('SELF','SUPERVISOR','CALIBRATED'));
CREATE TABLE ${primehrSchema}.spms_calibration_case(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,rating_case_id VARCHAR(36) NOT NULL,supervisor_assessment_id VARCHAR(36) NOT NULL,pmt_id VARCHAR(36) NOT NULL,roster_revision INT NOT NULL,quorum_required INT NOT NULL,eligible_voters INT NOT NULL,decision_count INT NOT NULL DEFAULT 0,proposal_assessment_id VARCHAR(36),status VARCHAR(30) NOT NULL,opened_by VARCHAR(100) NOT NULL,opened_at DATETIMEOFFSET NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_spms_calibration_rating FOREIGN KEY(rating_case_id) REFERENCES ${primehrSchema}.spms_rating_case(id),CONSTRAINT fk_spms_calibration_supervisor FOREIGN KEY(supervisor_assessment_id) REFERENCES ${primehrSchema}.spms_rating_assessment(id),CONSTRAINT fk_spms_calibration_pmt FOREIGN KEY(pmt_id) REFERENCES ${primehrSchema}.spms_pmt(id),CONSTRAINT fk_spms_calibration_proposal FOREIGN KEY(proposal_assessment_id) REFERENCES ${primehrSchema}.spms_rating_assessment(id),CONSTRAINT uk_spms_calibration_rating UNIQUE(agency_id,rating_case_id),CONSTRAINT ck_spms_calibration_status CHECK(status IN ('OPEN','PROPOSAL_SUBMITTED','APPROVED','REJECTED','FINALIZED')),CONSTRAINT ck_spms_calibration_quorum CHECK(quorum_required>0 AND eligible_voters>=quorum_required));
CREATE TABLE ${primehrSchema}.spms_calibration_participant(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,calibration_case_id VARCHAR(36) NOT NULL,employee_no VARCHAR(100) NOT NULL,employee_name VARCHAR(300) NOT NULL,member_role VARCHAR(30) NOT NULL,voting BIT NOT NULL,decision_eligible BIT NOT NULL,conflict_reason VARCHAR(200),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_spms_calibration_participant_case FOREIGN KEY(calibration_case_id) REFERENCES ${primehrSchema}.spms_calibration_case(id),CONSTRAINT uk_spms_calibration_participant UNIQUE(agency_id,calibration_case_id,employee_no));
CREATE TABLE ${primehrSchema}.spms_calibration_decision(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,calibration_case_id VARCHAR(36) NOT NULL,employee_no VARCHAR(100) NOT NULL,decision VARCHAR(20) NOT NULL,rationale VARCHAR(2000) NOT NULL,decided_at DATETIMEOFFSET NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_spms_calibration_decision_case FOREIGN KEY(calibration_case_id) REFERENCES ${primehrSchema}.spms_calibration_case(id),CONSTRAINT uk_spms_calibration_decision UNIQUE(agency_id,calibration_case_id,employee_no),CONSTRAINT ck_spms_calibration_decision CHECK(decision IN ('APPROVE','REJECT','ABSTAIN')));
CREATE TABLE ${primehrSchema}.spms_final_rating(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,rating_case_id VARCHAR(36) NOT NULL,revision_no INT NOT NULL,source_assessment_id VARCHAR(36) NOT NULL,calibration_case_id VARCHAR(36),raw_score DECIMAL(19,8) NOT NULL,rounded_score DECIMAL(19,6) NOT NULL,rating_band_id VARCHAR(36) NOT NULL,rating_label VARCHAR(200) NOT NULL,calculation_fingerprint VARCHAR(64) NOT NULL,finalized_by VARCHAR(100) NOT NULL,finalized_at DATETIMEOFFSET NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_spms_final_rating_case FOREIGN KEY(rating_case_id) REFERENCES ${primehrSchema}.spms_rating_case(id),CONSTRAINT fk_spms_final_rating_assessment FOREIGN KEY(source_assessment_id) REFERENCES ${primehrSchema}.spms_rating_assessment(id),CONSTRAINT fk_spms_final_rating_calibration FOREIGN KEY(calibration_case_id) REFERENCES ${primehrSchema}.spms_calibration_case(id),CONSTRAINT fk_spms_final_rating_band FOREIGN KEY(rating_band_id) REFERENCES ${primehrSchema}.spms_rating_band(id),CONSTRAINT uk_spms_final_rating_revision UNIQUE(agency_id,rating_case_id,revision_no));
CREATE INDEX ix_spms_calibration_status ON ${primehrSchema}.spms_calibration_case(agency_id,status);
CREATE INDEX ix_spms_final_rating_case ON ${primehrSchema}.spms_final_rating(agency_id,rating_case_id);
